import{_ as e,o as t,c as i,ag as o}from"./chunks/framework.BSsJcWLc.js";const p=JSON.parse('{"title":"Data Acquisition","description":"","frontmatter":{},"headers":[],"relativePath":"guides/data-acquisition.md","filePath":"guides/data-acquisition.md"}'),n={name:"guides/data-acquisition.md"};function s(r,a,c,l,d,h){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="data-acquisition" tabindex="-1">Data Acquisition <a class="header-anchor" href="#data-acquisition" aria-label="Permalink to &quot;Data Acquisition&quot;">​</a></h1><p>Dendrite connects to any LSL-compatible amplifier.</p><h2 id="discovering-streams" tabindex="-1">Discovering Streams <a class="header-anchor" href="#discovering-streams" aria-label="Permalink to &quot;Discovering Streams&quot;">​</a></h2><p>Open the <strong>Configure Streams</strong> dialog from the control panel. Click <strong>Rescan</strong> to discover all LSL outlets on the network. Each stream shows its name, type, channel count, and sampling rate. Toggle streams on/off, then click <strong>Apply</strong> to finalize your selection.</p><p>You can also discover streams via the API: <code>POST /api/streams/discover</code>.</p><h2 id="channel-configuration" tabindex="-1">Channel Configuration <a class="header-anchor" href="#channel-configuration" aria-label="Permalink to &quot;Channel Configuration&quot;">​</a></h2><p>The stream setup dialog pre-populates channel labels and types from the LSL stream descriptor. Some devices send generic labels (Ch1, Ch2...) or incorrect types. Review and correct before starting.</p><h2 id="starting-acquisition" tabindex="-1">Starting Acquisition <a class="header-anchor" href="#starting-acquisition" aria-label="Permalink to &quot;Starting Acquisition&quot;">​</a></h2><p>Click <strong>Start</strong> to begin recording. The dashboard shows per-stream latency — high latency usually indicates network congestion or an overloaded source machine.</p><p>Click <strong>Stop</strong> to end the session. All data is saved automatically to HDF5.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./send-events.html">Send Events</a> — Send event markers from task applications</li></ul>',12)])])}const g=e(n,[["render",s]]);export{p as __pageData,g as default};
